import { Box3 } from 'three'
import { Mesh2MotionEngine } from './Mesh2MotionEngine'

export class CustomModelUploadBootstrap {
  public readonly mesh2motion_engine: Mesh2MotionEngine

  constructor () {
    this.mesh2motion_engine = new Mesh2MotionEngine()
  }
}

// instantiate the class to setup event listeners
const app = new CustomModelUploadBootstrap()

// Companion Core: "?modelo=<url>" abre o modelo direto (o Administrador passa o .GLB do Companion ou do monstro)
const model_url = new URLSearchParams(location.search).get('modelo')
if (model_url !== null) {
  // o carregador aceita o endereço direto (é o mesmo caminho do arquivo enviado pela tela)
  app.mesh2motion_engine.load_model_step.load_model_file(new URL(model_url, location.href).href, 'glb')
}

// Companion Core: caixa do modelo aberto (o esqueleto salvo é esticado para ela)
;(window as unknown as { __cc_model_box: () => Box3 | null }).__cc_model_box = () => {
  const meshes = app.mesh2motion_engine.load_model_step.model_meshes()
  if (meshes.children.length === 0) return null
  return new Box3().setFromObject(meshes)
}

// Companion Core: a malha aberta (para o encaixe automático)
;(window as unknown as { __cc_model_meshes: () => unknown }).__cc_model_meshes = () => {
  const meshes = app.mesh2motion_engine.load_model_step.model_meshes()
  return meshes.children.length === 0 ? null : meshes
}

// Companion Core: "?sozinho=<tipo>" faz tudo sem ninguém clicar: escolhe o esqueleto, encaixa (com "&auto=1"), liga a
// malha aos ossos e devolve o arquivo ao Administrador. Companion (human) volta sem animações (o pacote padrão vem
// depois); bicho volta com todas as animações do molde dele. Avisa o andamento e os erros por mensagem.
const solo = new URLSearchParams(location.search).get('sozinho')
if (solo !== null && model_url !== null) {
  const eng = app.mesh2motion_engine
  const host: Window | null = window.parent !== window ? window.parent : null
  const say = (type: string, extra: Record<string, unknown> = {}): void => { host?.postMessage({ type, ...extra }, location.origin) }
  const wait = async (ok: () => boolean, ms = 90000): Promise<void> => await new Promise((resolve, reject) => {
    const t0 = performance.now()
    const tick = (): void => { if (ok()) resolve(); else if (performance.now() - t0 > ms) reject(new Error('demorou demais')); else setTimeout(tick, 100) }
    tick()
  })
  const step = (): string => String(eng.process_step)
  let started = false
  eng.load_model_step.addEventListener('modelLoaded', () => {
    if (started) return
    started = true
    void (async () => {
      try {
        say('m2m-progress', { stage: 'esqueleto' })
        await wait(() => step() === 'load-skeleton' || document.querySelector('#skeleton-selection') !== null)
        const sel = document.querySelector<HTMLSelectElement>('#skeleton-selection')
        const btn = document.querySelector<HTMLButtonElement>('#load-skeleton-button')
        if (sel === null || btn === null) throw new Error('editor sem a escolha de esqueleto')
        if (![...sel.options].some((o) => o.value === solo)) throw new Error('esqueleto desconhecido: ' + solo)
        sel.value = solo
        sel.dispatchEvent(new Event('change'))
        await wait(() => !btn.disabled)
        say('m2m-progress', { stage: 'encaixe' })
        btn.click()
        await wait(() => step() === 'edit-skeleton')
        // deixa o encaixe aparecer um instante (a pessoa vê o que vai ser ligado)
        await new Promise((resolve) => setTimeout(resolve, 600))
        say('m2m-progress', { stage: 'pele', fit: (window as unknown as { __cc_autofit?: unknown }).__cc_autofit ?? null })
        document.querySelector<HTMLButtonElement>('#action_bind_pose')?.click()
        await wait(() => step() === 'animations-export')
        const clips = (): ReturnType<typeof eng.animations_listing_step.animation_clips> => eng.animations_listing_step.animation_clips()
        if (solo !== 'human') await wait(() => clips().length > 0, 60000)
        const selections = solo === 'human' ? [] : clips().map((c, i) => ({ c, i })).filter(({ c }) => !/rest[ _]?pose/i.test(c.name)).map(({ i }) => ({ animation_index: i, mirror_export_mode: 'none' as const }))
        say('m2m-progress', { stage: 'arquivo' })
        eng.file_export_step.set_animation_clips_to_export(clips(), selections)
        await eng.file_export_step.export(eng.animations_listing_step.active_skinned_meshes(), 'exported-model', eng.download_settings)
      } catch (err) {
        say('m2m-error', { message: err instanceof Error ? err.message : String(err) })
      }
    })()
  })
}
